// 只读沿边法向灰度/BGR剖面；保留每个独立边界像素的九个邻域采样。
#include <opencv2/opencv.hpp>
#include <iostream>
#include <set>
#include <iomanip>
int main(){std::string group,key,path;int n;cv::setNumThreads(1);while(std::cin>>group>>key>>path>>n){std::set<std::pair<int,int>> unique;for(int i=0;i<n;++i){int x,y;std::cin>>x>>y;unique.emplace(x,y);}auto image=cv::imread(path);if(image.empty())return 2;cv::Mat gray;cv::cvtColor(image,gray,cv::COLOR_BGR2GRAY);std::vector<cv::Point2f> points;for(auto q:unique)points.emplace_back(q.first,q.second);cv::Vec4f line;cv::fitLine(points,line,cv::DIST_L2,0,.01,.01);cv::Point2f normal(-line[1],line[0]);size_t samples=0,mid=0,colored=0,reversal=0,profiles=0;double channel_diff=0;for(auto point:points){std::vector<int> values;for(int k=-4;k<=4;++k){auto q=point+normal*k;int x=cvRound(q.x),y=cvRound(q.y);if(x<0||y<0||x>=image.cols||y>=image.rows)continue;int v=gray.at<unsigned char>(y,x);auto bgr=image.at<cv::Vec3b>(y,x);int diff=std::max({bgr[0],bgr[1],bgr[2]})-std::min({bgr[0],bgr[1],bgr[2]});++samples;mid+=(v>20&&v<235);colored+=diff>20;channel_diff+=diff;values.push_back(v);}if(values.size()==9){++profiles;bool pos=false,neg=false;for(size_t k=1;k<values.size();++k){pos|=values[k]-values[k-1]>10;neg|=values[k-1]-values[k]>10;}reversal+=(pos&&neg);}}std::cout<<std::setprecision(17)<<"{\"group\":\""<<group<<"\",\"key\":\""<<key<<"\",\"samples\":"<<samples<<",\"mid_gray_samples\":"<<mid<<",\"colored_samples\":"<<colored<<",\"mean_channel_difference\":"<<channel_diff/samples<<",\"profiles\":"<<profiles<<",\"nonmonotone_profiles\":"<<reversal<<"}\n";}}
